using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;using RaceDay.Mvc.Models;namespace RaceDay.Mvc.Controllers;public class AccountController(RaceApi api):Controller{public IActionResult Login()=>View(new LoginForm());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Login(LoginForm f){if(!ModelState.IsValid)return View(f);var r=await api.Login(f.Email,f.Password);if(!r.ok){ModelState.AddModelError("",r.error);return View(f);}return RedirectToAction("Index","Dashboard");}public IActionResult Register()=>View(new RegisterForm());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Register(RegisterForm f){if(!ModelState.IsValid)return View(f);var r=await api.Send(HttpMethod.Post,"api/auth/register",f);if(!r.ok){ModelState.AddModelError("",r.error);return View(f);}TempData["Notice"]="Account created. Please sign in.";return RedirectToAction(nameof(Login));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Logout(){await api.Send(HttpMethod.Post,"api/auth/logout");HttpContext.Session.Clear();return RedirectToAction("Index","Home");}}